	       ,SUM(NVL(DECODE(SUBSTR(WORK_DT,7,2),'07', DECODE(OT_TYPE,'NT',(OT_TIME),0), 0), 0)) N7
	       ,SUM(NVL(DECODE(SUBSTR(WORK_DT,7,2),'08', DECODE(OT_TYPE,'NT',(OT_TIME),0), 0), 0)) N8
