		AV_2   := SUBSTR(text_buffer, 1, INSTR(AV_TEMP, "	") - 1);
		AV_TEMP := SUBSTR(text_buffer, LENGTH(AV_SEQ) + 1, LENTH(text_buffer) - LENTH(AV_SEQ))
