BEGIN
	 --lay so hop dong
	 outResult :=1;
	SELECT  a.CODE_lNM	INTO AV_SEQ_CONTRACT FROM COMM.TCO_ABCODE a, COMM.TCO_ABCODEGRP b 
	 WHERE a.del_if=0 AND b.del_if=0 AND b.ID='HRAB0030' AND a.TCO_ABCODEGRP_PK=b.PK AND a.code='0';
	
