	  ,inBIRTH_DATE		 		   	-- 11
	  ,inPLACE_BIRTH_DATE		 		   	-- 12
	  ,inPERSON_ID		 		   	-- 13
	  ,inISSUE_DATE		 		   	-- 14
	  ,inPLACE_PER_ID		 		   	-- 15
	  ,inJOIN_DT		 		   	-- 16
	  ,inNATION_CODE		 		   	-- 17
	  ,inEDU_CODE		 		   	-- 18
	  ,inMARRIED		 		   	-- 19
	  ,inCHILDREN_CNT		 		   	-- 20
