	  ,inETHNIC_CD		 		   	-- 23
	  ,inRELIG_CD		 		   	-- 24
	  ,inCITY_CODE		 		   	-- 25
	  ,inEMP_STATUS		 		   	-- 26
	  ,inPERIOD_CONTRACT		 		   	-- 27
	  ,inST_CONTRACT		 		   	-- 28
	  ,inET_CONTRACT		 		   	-- 29
	  ,inST_PROBATION		 		   	-- 30
	  ,inET_PROBATION		 		   	-- 31
	  ,AV_SEQ_CONTRACT		 		   	-- 32
	  --,inBASIC_SAL 		 		   	-- 
	  --,inPROFESSION_SKILL   		 		   	-- 
	  ,inMOD_BY		 		   	-- 
	  ,SYSDATE		 		   	-- 
	  ,0		 		   	-- 
	  ,inFULL_NM_N		 		   	-- 
	  ,inEMP_ID_STYLE		 		   	-- 
	  );

	  ERROR_NUM := '50';
	   outResult :=3;
	   l_status := 'insert THR_ABEMPMAS';
    INSERT INTO THR_ABEMPMAS B
	(B.PK,
	B.THR_ABEMP_PK,
	B.VALID_FROM,
	B.SOCIAL_NO,
	B.SOCIAL_FDATE,
	B.POS_AMT,
	B.SOCIAL_PLACE,
	B.SOCIAL_YN,
	B.THR_ABWORKGROUP_PK,
	B.TCO_EODEPT_PK,
	B.HEALTH_NO,
	B.HEALTH_FDATE,
	B.HEALTH_TDATE,
	B.HEALTH_PLACE,
	B.HEALTH_YN,
	B.JOB_CODE,
	B.POS_CODE,
	B.TCO_EOFACTORY_PK,
	B.BASIC_SAL,
	--B.PROB_MON,
	B.PROB_SALARY,
	B.BANK_ACCOUNT,
	B.CARD_AMT,
	B.REMAINING_CARD_AMT,
	B.PAY_TYPE,
	B.SAL_ALLOW,
	B.TECH_AMT,
	B.HARD_WORK_AMT,
	B.OTHER_AMT,
	B.CRT_BY,
	B.CRT_DT,
	B.DEL_IF
	)
	VALUES
	(
