	 ,inHEALTH_FDATE
	 ,inHEALTH_TDATE
	 ,inHEALTH_PLACE
	 ,inHEALTH_FLAG
	 ,inJOB_CODE
	 ,inPOS_CODE
	 ,inFACT_CD
	 ,inBASIC_SAL
	 ,inPROB_SALARY
	 --,inBASIC_SAL
	 ,inACCOUNT
	 ,inCARD_AMT
