	 ,inSAL_ALLOW
	 ,inTECH_AMT
	 ,inHARD_WORK_AMT
	 ,inOTHER_AMT
	 ,inMOD_BY
	 ,SYSDATE
	 ,0);

	 ERROR_NUM := '60';
	  outResult :=4;
	 l_status := 'insert THR_EMP_HIST';
	INSERT INTO THR_EMP_HIST (
