	   ,PERSON_ID
	   ,ISSUE_DT
	   ,PLACE_PER_ID
	   ,SOCIAL_NO
	   ,SOCIAL_DT
	   --,SOCIAL_DT_TO
	   ,SOCIAL_PLACE
