	   ,DEPT_PK
	   ,EDU_CODE
	   ,MARRIED
	   ,CHILDREN_CNT
	   ,HEALTH_NO
	   ,HEALTH_DT
	   ,HEALTH_DT_TO
	   ,HEALTH_PLACE
	   ,HEALTH_FLAG
	   ,LEFT_DT
	   ,TEL
	   ,ETHNIC_CD
	   ,RELIG_CD
	   ,JOB_CODE
	   ,POS_CODE
	   ,CITY_CODE
	   ,FACT_CD
	   ,STATUS
	   ,BASIC_SAL
	   ,PERIOD_CONTRACT
	   ,ST_CONTRACT
	   ,ET_CONTRACT
	   ,ST_PROBATION
	   ,ET_PROBATION
	   ,SEQ_CONTRACT
	   --PROB_MON
	   ,PROB_SAL
	   --,BASIC_SAL
	   ,PAY_TYPE
	   ,CRT_DT
	   ,CRT_BY
	   ,DEL_IF
	  )
	  VALUES
	  (
	   AV_EMP_HIST_SEQ
	   ,AV_ABEMP_SEQ
	   ,AV_EMPID
	   ,inREMARK
	   ,inCARD_ID
	   ,inFULL_NAME
	   ,inFULL_NAME_ENG
	   ,inPHOTO_PK
	   ,inLIVING_ADDR
	   ,inPERMANENT_ADDR
	   ,inSEX
	   ,inBIRTH_DATE
	   ,inPLACE_BIRTH_DATE
	   ,inPERSON_ID
	   ,inISSUE_DATE
	   ,inPLACE_PER_ID
	   ,inSOCIAL_NO
	   ,inSOCIAL_FDATE
	   --,inSOCIAL_TDATE
	   ,inSOCIAL_PLACE
	   ,inSOCIAL_FLAG
	   ,inJOIN_DT
	   ,inNATION_CODE
	   ,DECODE(inGRP_CODE,0,NULL,inGRP_CODE)
	   ,DECODE(inDEPT_PK,0,NULL,inDEPT_PK)
	   ,inEDU_CODE
	   ,inMARRIED
	   ,inCHILDREN_CNT
	   ,inHEALTH_NO
	   ,inHEALTH_FDATE
	   ,inHEALTH_TDATE
	   ,inHEALTH_PLACE
	   ,inHEALTH_FLAG
	   ,inLEFT_DT
	   ,inTEL
	   ,inETHNIC_CD
	   ,inRELIG_CD
	   ,inJOB_CODE
	   ,inPOS_CODE
	   ,inCITY_CODE
	   ,inFACT_CD
	   ,inEMP_STATUS
	   ,inBASIC_SAL
	   ,inPERIOD_CONTRACT
	   ,inST_CONTRACT
	   ,inET_CONTRACT
	   ,inST_PROBATION
	   ,inET_PROBATION
	   ,AV_SEQ_CONTRACT
	   --inPROB_MON
	   ,inPROB_SALARY
	   --,inBASIC_SAL
	   ,inPAY_TYPE
	   ,SYSDATE
	   ,inMOD_BY
	   ,0
	   );

	    outResult :=5;
	   ERROR_NUM := '70';
	  INSERT INTO THR_GRP_EMP(
			       PK, THR_ABWORKGRP_PK, EMP_PK, FULL_NAME, START_DT, END_DT
			       ,WORK_SHIFT,WT,OT,NT, DEL_IF, CRT_DT, CRT_BY)
            SELECT THR_GRP_EMP_SEQ.NEXTVAL,A.THR_ABWORKGRP_PK, c.pk, C.FULL_NAME, A.WORK_DATE, A.WORK_DATE
                   ,A.THR_WORK_SHIFT_PK,WT,OT,NT, 0, SYSDATE, inMOD_BY
              FROM THR_ABWORKGRPDDSCH A, VHR_EMP C
             WHERE A.DEL_IF = 0  AND C.DEL_IF = 0 AND C.STATUS = 'A' 
			 AND c.grp_code=a.THR_ABWORKGRP_PK
               AND C.PK=AV_ABEMP_SEQ
               AND A.WORK_DATE >= inJOIN_DT AND A.THR_ABWORKGRP_PK = inGRP_CODE;
	--xu ly phep nam cho nhan vien moi vao
	IF SUBSTR(inJOIN_DT,4) < TO_CHAR(SYSDATE,'yyyy') THEN
	/*	IF inDEPT_PK =4 THEN
		   AV_AL_IN_YEAR :=12;
		   AV_AL := 12;
			
		ELSIF (inPOS_CODE ='A' OR inPOS_CODE='N' OR inPOS_CODE='O' OR inPOS_CODE ='P' OR inPOS_CODE='B' OR inPOS_CODE='X') THEN 
			  AV_AL_IN_YEAR :=14;
			  AV_AL := 14;
		ELSE 
		   AV_AL_IN_YEAR :=12;
		   AV_AL := 12;
		END IF;	 */
		AV_AL_IN_YEAR :=14;
		AV_AL := 14;
	ELSE
		AV_AL:=14-TO_NUMBER(SUBSTR(inJOIN_DT,5,2));
		AV_AL_IN_YEAR :=14;
	END IF;			  
				
		UPDATE THR_ABEMP B
        SET B.ANNUAL_LEAVE_DAYS = AV_AL,
		          B.ANNUAL_LEAVE_DAYS_IN_YEAR = AV_AL_IN_YEAR
            WHERE B.DEL_IF=0
  	  		AND B.ANNUALY_APPLY_FLAG <>'Y'
  	    	AND B.PK = AV_ABEMP_SEQ; 	
	--tao hop dong thu viec cho nhan vien		
	 outResult :=6;
	 IF inPERIOD_CONTRACT IS NOT NULL THEN
	   	  INSERT INTO THR_LABOUR_CONTRACT
		  ( 
			PK 		,
			THR_ABEMP_PK   	,
			CONTRACT_NO ,
			ST_PROBATION ,
			ET_PROBATION ,
			ST_CONTRACT ,
			ET_CONTRACT ,
			KIND_CONTRACT ,
			BASIC_SALARY ,
			NON_ABSENT ,
			TIMES,
			DEL_IF ,
			CTR_By,
			CTR_DT
			) 
		  VALUES
		  (
		    THR_LABOUR_CONTRACT_SEQ.NEXTVAL,
			AV_ABEMP_SEQ   	,
			AV_SEQ_CONTRACT ,
			inST_PROBATION ,
			inET_PROBATION ,
			NULL ,
			NULL ,
			inPERIOD_CONTRACT ,
			0,
			0 ,
			1,
			0 ,
			inMOD_BY	,
			SYSDATE
		  ) ;	
		END IF;	 
		 	  
		l_status := 'success';
		outOUT_PK := AV_ABEMP_SEQ;
		outResult := 0;
RETURN;
---------
EXCEPTION
---------
  WHEN  NO_DATA_FOUND  THEN
        outResult  := -1;
		RAISE_APPLICATION_ERROR(-20001,ERROR_NUM||'Procedure error 1: '||SQLERRM);
	ROLLBACK WORK;
        RETURN;

  WHEN  OTHERS  THEN
        outResult  := -1;
		DBMS_OUTPUT.PUT_LINE('EMP ID: '||AV_ABEMP_SEQ);
		RAISE_APPLICATION_ERROR(-20002,ERROR_NUM||'Procedure error 2: '||SQLERRM);
	ROLLBACK WORK;
        RETURN;

END;
