		L_STATUS:='|LOGGED|' || SQLCODE || '|' || SQLERRM || '|' || L_STATUS || '|' || L_SEQ_NUMBER || '|'; 
		RAISE_APPLICATION_ERROR(-20002,L_STATUS);
       
