		   0 A31
	FROM THR_TIME_MACHINE
	WHERE WORK_DT LIKE  AV_MON || '%'
	  AND DEL_IF = 0
	  AND NVL(APPLY_FLAG, 'N') = 'N'
	  GROUP BY  EMP_PK
	UNION ALL
	SELECT EMP_PK,
	        0  D1,
