--	,JOB_CODE
--	,POS_CODE
--	,BASIC_SAL
--	,ALLOW_AMT
--	,CERT_ALLOW_AMT
--	,BIRTH_DT	 
--	,PLACE_BIRTH_DT
--	,SEX
--	,ADDR
--	,PER_ADDR
--	,TEL
--	,PER_CONTACT
--	,NATION_CODE
--	,JOIN_DT
--	,EDU_CODE
--	,LEFT_DT
--	,CITY_CODE
--	,PERSON_ID
